CREATE OR REPLACE FUNCTION public.c3_free_snapshot_immutable_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_context text:=current_setting('c3.pac_registrar_context',true);
begin
  if tg_op='DELETE' then
    raise exception 'FREE registered snapshot cannot be deleted';
  end if;

  if nullif(v_context,'') is null then
    raise exception 'FREE registered snapshot is immutable; supersede through Registrar';
  end if;

  if (
    new.free_snapshot_key is distinct from old.free_snapshot_key
    or new.pac_key is distinct from old.pac_key
    or new.schema_key is distinct from old.schema_key
    or new.free_call_key is distinct from old.free_call_key
    or new.encounter_key is distinct from old.encounter_key
    or new.surface_type is distinct from old.surface_type
    or new.selector_type is distinct from old.selector_type
    or new.selector_value is distinct from old.selector_value
    or new.registration_sha256 is distinct from old.registration_sha256
    or new.projection_sha256 is distinct from old.projection_sha256
    or new.projection is distinct from old.projection
    or new.registrar_role_call_key is distinct from old.registrar_role_call_key
    or new.registered_at is distinct from old.registered_at
  ) then
    raise exception 'FREE registered snapshot content cannot be mutated';
  end if;

  if old.standing='active' and new.standing in ('superseded','revoked') and new.superseded_at is not null then
    return new;
  end if;

  if new.standing is distinct from old.standing or new.superseded_at is distinct from old.superseded_at then
    raise exception 'FREE registered snapshot standing transition is invalid';
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.c3_guard_profile_pac_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_envpac_key text;
  v_owner_type text;
  v_owner_key text;
  v_formed_from_c1 boolean;
  v_primitive_ok boolean;
  v_registration_protocol text;
  v_schema_key text;
  v_contract_key text;
  v_environment_class text;
  v_parent_environment text;
begin
  select p.envpac_key,p.registration_protocol,p.schema_key,p.contract_key
    into v_envpac_key,v_registration_protocol,v_schema_key,v_contract_key
  from public.c3_pac p
  where p.pac_key=new.pac_key
    and p.pac_type='ProfilePAC'
    and p.is_effective=true;

  if v_envpac_key is null then
    raise exception 'DNR_PROFILE_CHAIN: effective ProfilePAC base record not resolved';
  end if;

  if v_registration_protocol='registrar_v1' then
    if not exists(
      select 1
      from public.c3_pac_schema s
      where s.schema_key=v_schema_key
        and s.pac_type='ProfilePAC'
        and s.standing='active'
        and s.is_active=true
    ) then
      raise exception 'DNR_PROFILE_CHAIN: active ProfilePAC schema not resolved';
    end if;
  elsif v_contract_key is distinct from 'pac_contract_profilepac_v1' then
    raise exception 'DNR_PROFILE_CHAIN: legacy ProfilePAC contract not resolved';
  end if;

  select e.owner_subject_type,
         e.owner_subject_key,
         coalesce((e.metadata->>'formed_from_c1')::boolean,false),
         ce.environment_class,
         ce.metadata->>'parent_environment'
    into v_owner_type,v_owner_key,v_formed_from_c1,v_environment_class,v_parent_environment
  from public.c3_envpac e
  join public.c3_environment ce on ce.env_key=e.env_key and ce.is_active=true
  where e.envpac_key=v_envpac_key
    and e.is_effective=true;

  if v_owner_key is null then
    raise exception 'DNR_PROFILE_CHAIN: effective ProfilePAC EnvPAC not resolved';
  end if;

  if v_registration_protocol='registrar_v1' then
    if v_owner_type<>'individual'
       or not v_formed_from_c1
       or v_environment_class<>'c3me_individual_environment'
       or v_parent_environment<>'env_c3_community_connect' then
      raise exception 'DNR_PROFILE_CHAIN: hardened ProfilePAC requires current personal c1My_Env lineage';
    end if;
  else
    if not v_formed_from_c1 then
      raise exception 'DNR_PROFILE_CHAIN: ProfilePAC requires effective personal c1My_Env formed from Connect';
    end if;

    select exists(
      select 1
      from public.c3_envpac_runtime_primitive rp
      where rp.envpac_key=v_envpac_key
        and rp.primitive_key='profile_pac'
        and rp.primitive_class='participant_formable_pac'
        and rp.standing='active'
        and rp.config->>'contract_key'='pac_contract_profilepac_v1'
    ) into v_primitive_ok;

    if not v_primitive_ok then
      raise exception 'DNR_PROFILE_CHAIN: active ProfilePAC primitive not resolved from c1My_Env';
    end if;
  end if;

  if new.subject_type is distinct from v_owner_type
     or new.subject_key is distinct from v_owner_key then
    raise exception 'DNR_PROFILE_CHAIN: ProfilePAC subject must equal c1My_Env owner';
  end if;

  if tg_op='UPDATE' then
    if new.subject_type is distinct from old.subject_type
       or new.subject_key is distinct from old.subject_key
       or new.profile_class is distinct from old.profile_class then
      raise exception 'DNR_PROFILE_CHAIN: ProfilePAC identity binding is immutable after formation';
    end if;
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.c3_guard_registrar_pac_supersession_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result jsonb;
begin
  if new.registration_protocol='registrar_v1'
     and new.supersedes_pac_key is not null then
    v_result:=public.c3_validate_pac_supersession_v1(to_jsonb(new),true);

    if coalesce(v_result->>'standing','HLD')<>'PASS' then
      raise exception 'HLD_PAC_SUPERSESSION:%',
        coalesce(v_result->>'reason','supersession_unresolved');
    end if;
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.c3_hardened_pac_child_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_parent_column text := nullif(TG_ARGV[0],'');
  v_old_pac_key text;
  v_new_pac_key text;
  v_old_protocol text;
  v_new_protocol text;
  v_context text := current_setting('c3.pac_registrar_context',true);
begin
  if v_parent_column is null then
    raise exception 'hardened PAC child guard parent key argument is required';
  end if;

  if TG_OP in ('UPDATE','DELETE') then
    v_old_pac_key := nullif(to_jsonb(OLD)->>v_parent_column,'');
    if v_old_pac_key is null then
      raise exception 'hardened PAC child guard old parent unresolved for table % column %',
        TG_TABLE_NAME, v_parent_column;
    end if;

    select registration_protocol
      into v_old_protocol
    from public.c3_pac
    where pac_key=v_old_pac_key;
  end if;

  if TG_OP in ('INSERT','UPDATE') then
    v_new_pac_key := nullif(to_jsonb(NEW)->>v_parent_column,'');
    if v_new_pac_key is null then
      raise exception 'hardened PAC child guard new parent unresolved for table % column %',
        TG_TABLE_NAME, v_parent_column;
    end if;

    select registration_protocol
      into v_new_protocol
    from public.c3_pac
    where pac_key=v_new_pac_key;
  end if;

  if nullif(v_context,'') is null
     and (v_old_protocol='registrar_v1' or v_new_protocol='registrar_v1') then
    raise exception 'registrar_v1 PAC child state is immutable; supersede through Registrar';
  end if;

  if TG_OP='DELETE' then
    return OLD;
  end if;
  return NEW;
end $function$

CREATE OR REPLACE FUNCTION public.c3_pac_registrar_v1_completeness_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_eval public.c3_pac_boundary_evaluation%rowtype;
  v_call public.c3_ci_role_call%rowtype;
begin
  if new.registration_protocol<>'registrar_v1' then return null; end if;

  select * into v_eval from public.c3_pac_boundary_evaluation where evaluation_key=new.boundary_evaluation_key;
  if not found or v_eval.notchazz_result<>'PASS' or v_eval.presented_registration_sha256<>new.registration_sha256 then
    raise exception 'registrar_v1_boundary_pass_exact_match_required';
  end if;

  if not exists(
    select 1 from public.c3_pac_schema
    where schema_key=new.schema_key and pac_type=new.pac_type and standing='active' and is_active=true
  ) then
    raise exception 'registrar_v1_active_schema_required';
  end if;

  if coalesce((select requires_c3_model_binding from public.c3_pac_schema where schema_key=new.schema_key),true)
     and not exists(select 1 from public.c3_pac_model_binding b where b.pac_key=new.pac_key and b.standing='active') then
    raise exception 'registrar_v1_model_binding_required';
  end if;

  if not exists(select 1 from public.c3_pac_encounter_scope s where s.pac_key=new.pac_key and s.standing='active') then
    raise exception 'registrar_v1_encounter_scope_required';
  end if;

  select * into v_call
  from public.c3_ci_role_call
  where role_call_key=new.registrar_role_call_key;

  if not found
     or v_call.call_class<>'pac_registration'
     or v_call.caller_role_key<>'c3_notchazz_boundary_v1'
     or v_call.callee_role_key<>'c3_registrar_ci_v1'
     or v_call.standing<>'RETURNED'
     or v_call.boundary_evaluation_key<>new.boundary_evaluation_key
     or v_call.presented_sha256<>new.registration_sha256 then
    raise exception 'registrar_v1_role_call_required';
  end if;

  if not exists(
    select 1 from public.c3_pac_registration_receipt r
    where r.pac_key=new.pac_key
      and r.registration_sha256=new.registration_sha256
      and r.registrar_role_call_key=new.registrar_role_call_key
      and r.standing='registered'
  ) then
    raise exception 'registrar_v1_registration_receipt_required';
  end if;

  if new.owner_subject_type='institution'
     and coalesce((public.resolve_institutional_pac_eligibility_v1(new.owner_subject_key,new.owner_environment_key)->>'standing'),'HLD')<>'PASS' then
    raise exception 'HLD_INSTITUTIONAL_SEAT_REQUIRED';
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.c3_pac_set_personal_disposition_v1(p_pac_key text, p_subject_key text, p_disposition text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_pac public.c3_pac%rowtype;
  v_now timestamptz:=now();
  v_state text;
  v_current_hash text;
  v_review_hash text;
  v_existing_projection jsonb;
begin
  if p_disposition not in ('APPROVED','HLD') then
    return jsonb_build_object('standing','DNR','reason','unsupported_personal_disposition');
  end if;

  select * into v_pac
  from public.c3_pac
  where pac_key=p_pac_key and is_effective=true
  for update;

  if not found then
    return jsonb_build_object('standing','DNR','reason','pac_unavailable');
  end if;

  if v_pac.custodian_subject_type is distinct from 'individual'
     or v_pac.custodian_subject_key is distinct from p_subject_key
     or coalesce(v_pac.metadata#>>'{custody_model,custody_class}','')<>'personal_pac_custody'
     or coalesce(v_pac.metadata#>>'{ownership_model,owner_subject_type}','')<>'individual'
     or v_pac.metadata#>>'{ownership_model,owner_subject_key}' is distinct from p_subject_key then
    return jsonb_build_object('standing','DNR','reason','personal_owner_custody_required');
  end if;

  v_current_hash:=public.c3_pac_review_sha256_v1(p_pac_key);
  v_review_hash:=v_pac.metadata#>>'{review_resolution,review_snapshot_hash}';
  v_existing_projection:=coalesce(v_pac.metadata->'encounter_projection','{}'::jsonb);

  if p_disposition='APPROVED' and (
      coalesce(v_pac.metadata#>>'{review_resolution,standing}','')<>'REVIEWED'
      or v_review_hash is distinct from v_current_hash
  ) then
    return jsonb_build_object(
      'standing','DNR',
      'reason','current_review_required',
      'current_snapshot_hash',v_current_hash,
      'review_snapshot_hash',v_review_hash
    );
  end if;

  v_state:=case when p_disposition='APPROVED' then 'ACT' else 'HLD' end;

  update public.c3_pac
  set metadata=coalesce(metadata,'{}'::jsonb)
    || jsonb_build_object(
      'custody_approval',jsonb_build_object(
        'standing',p_disposition,
        'subject_key',p_subject_key,
        'context_class','personal_custody',
        'approval_surface','my_pacs',
        'approval_snapshot_hash',case when p_disposition='APPROVED' then v_current_hash else null end,
        'note',nullif(btrim(coalesce(p_note,'')),''),
        'resolved_at',v_now
      ),
      'encounter_projection',case
        when p_disposition='APPROVED'
             and coalesce(v_existing_projection->>'authorized_by_owner','false')='true'
          then v_existing_projection || jsonb_build_object(
            'authorization_snapshot_hash',v_current_hash,
            'reviewed_approval_bound_at',v_now
          )
        when p_disposition='APPROVED' then jsonb_build_object(
          'standing','PENDING',
          'encounter_key','c3envpac_c2me_v0_1',
          'owner_authorization_required',true,
          'authorized_by_owner',false,
          'projection_surface','c2ME_env',
          'reason','separate_owner_encounter_decision_required'
        )
        else jsonb_build_object(
          'standing','HLD',
          'encounter_key','c3envpac_c2me_v0_1',
          'owner_authorization_required',true,
          'authorized_by_owner',false,
          'projection_surface','c2ME_env',
          'reason','pac_not_approved_in_custody'
        )
      end,
      'distribution_resolution',case
        when p_disposition='APPROVED' then jsonb_build_object(
          'standing','HLD_OWNER_DISTRIBUTION_DECISION_REQUIRED',
          'review_snapshot_hash',v_current_hash,
          'approval_snapshot_hash',v_current_hash,
          'reason','approval_does_not_authorize_distribution'
        )
        else jsonb_build_object(
          'standing','HLD_PAC',
          'reason','pac_not_approved_in_custody'
        )
      end
    ),
    updated_at=v_now
  where pac_key=p_pac_key;

  return jsonb_build_object(
    'standing',v_state,
    'pac_key',p_pac_key,
    'disposition',p_disposition,
    'approval_surface','my_pacs',
    'approval_snapshot_hash',case when p_disposition='APPROVED' then v_current_hash else null end,
    'encounter_projection_standing',case
      when p_disposition='APPROVED' and coalesce(v_existing_projection->>'authorized_by_owner','false')='true'
        then coalesce(v_existing_projection->>'standing','AUTHORIZED')
      when p_disposition='APPROVED' then 'PENDING'
      else 'HLD'
    end,
    'encounter_authorization_preserved',
      p_disposition='APPROVED' and coalesce(v_existing_projection->>'authorized_by_owner','false')='true',
    'owner_encounter_decision_required',
      not (p_disposition='APPROVED' and coalesce(v_existing_projection->>'authorized_by_owner','false')='true'),
    'resolved_at',v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_pac_set_personal_encounter_projection_v1(p_pac_key text, p_subject_key text, p_action text, p_encounter_key text DEFAULT 'c3envpac_c2me_v0_1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_pac public.c3_pac%rowtype;
  v_now timestamptz:=now();
  v_authorized boolean;
  v_standing text;
begin
  if p_action not in ('AUTHORIZE','REVOKE') then
    return jsonb_build_object('standing','DNR','reason','unsupported_projection_action');
  end if;

  select * into v_pac
  from public.c3_pac
  where pac_key=p_pac_key and is_effective=true
  for update;

  if not found then
    return jsonb_build_object('standing','DNR','reason','pac_unavailable');
  end if;

  if v_pac.custodian_subject_type is distinct from 'individual'
     or v_pac.custodian_subject_key is distinct from p_subject_key
     or coalesce(v_pac.metadata#>>'{ownership_model,owner_subject_type}','')<>'individual'
     or v_pac.metadata#>>'{ownership_model,owner_subject_key}' is distinct from p_subject_key
     or coalesce(v_pac.metadata#>>'{custody_model,custody_class}','')<>'personal_pac_custody' then
    return jsonb_build_object('standing','DNR','reason','personal_owner_custody_required');
  end if;

  if p_action='AUTHORIZE'
     and coalesce(v_pac.metadata#>>'{custody_approval,standing}','')<>'APPROVED' then
    return jsonb_build_object('standing','DNR','reason','custody_approval_required');
  end if;

  v_authorized:=p_action='AUTHORIZE';
  v_standing:=case when v_authorized then 'AUTHORIZED' else 'REVOKED' end;

  update public.c3_pac
  set metadata=jsonb_set(
        coalesce(metadata,'{}'::jsonb),
        '{encounter_projection}',
        jsonb_build_object(
          'standing',v_standing,
          'encounter_key',p_encounter_key,
          'projection_surface','c2ME_env',
          'owner_authorization_required',true,
          'authorized_by_owner',v_authorized,
          'owner_subject_key',p_subject_key,
          'authorization_surface','my_pacs',
          'resolved_at',v_now
        ),
        true
      ),
      updated_at=v_now
  where pac_key=p_pac_key;

  return jsonb_build_object(
    'standing',case when v_authorized then 'ACT' else 'HLD' end,
    'pac_key',p_pac_key,
    'encounter_projection_standing',v_standing,
    'encounter_key',p_encounter_key,
    'authorized_by_owner',v_authorized,
    'resolved_at',v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_pac_set_personal_encounter_projection_v1(p_pac_key text, p_subject_key text, p_action text, p_encounter_key text DEFAULT 'c3envpac_c2me_v0_1'::text, p_surface_scope text DEFAULT 'c3field_only'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_pac public.c3_pac%rowtype;
  v_envpac public.c3_envpac%rowtype;
  v_now timestamptz:=now();
  v_authorized boolean;
  v_standing text;
  v_host text;
  v_url text;
  v_existing_reference uuid;
  v_current_hash text;
  v_review_hash text;
  v_approval_hash text;
begin
  if p_action not in ('AUTHORIZE','REVOKE') then
    return jsonb_build_object('standing','DNR','reason','unsupported_projection_action');
  end if;

  if p_surface_scope not in ('c3field_only','c3field_plus_canopy') then
    return jsonb_build_object('standing','DNR','reason','unsupported_surface_scope');
  end if;

  select * into v_pac
  from public.c3_pac
  where pac_key=p_pac_key and is_effective=true
  for update;

  if not found then
    return jsonb_build_object('standing','DNR','reason','pac_unavailable');
  end if;

  if v_pac.custodian_subject_type is distinct from 'individual'
     or v_pac.custodian_subject_key is distinct from p_subject_key
     or coalesce(v_pac.metadata#>>'{ownership_model,owner_subject_type}','')<>'individual'
     or v_pac.metadata#>>'{ownership_model,owner_subject_key}' is distinct from p_subject_key
     or coalesce(v_pac.metadata#>>'{custody_model,custody_class}','')<>'personal_pac_custody' then
    return jsonb_build_object('standing','DNR','reason','personal_owner_custody_required');
  end if;

  v_current_hash:=public.c3_pac_review_sha256_v1(p_pac_key);
  v_review_hash:=v_pac.metadata#>>'{review_resolution,review_snapshot_hash}';
  v_approval_hash:=v_pac.metadata#>>'{custody_approval,approval_snapshot_hash}';

  if p_action='AUTHORIZE' then
    if coalesce(v_pac.metadata#>>'{custody_approval,standing}','')<>'APPROVED' then
      return jsonb_build_object('standing','DNR','reason','custody_approval_required');
    end if;

    if coalesce(v_pac.metadata#>>'{review_resolution,standing}','')<>'REVIEWED'
       or v_review_hash is distinct from v_current_hash
       or v_approval_hash is distinct from v_current_hash then
      return jsonb_build_object(
        'standing','DNR',
        'reason','current_reviewed_approval_required',
        'current_snapshot_hash',v_current_hash,
        'review_snapshot_hash',v_review_hash,
        'approval_snapshot_hash',v_approval_hash
      );
    end if;
  end if;

  select * into v_envpac
  from public.c3_envpac
  where envpac_key=v_pac.envpac_key
    and owner_subject_type='individual'
    and owner_subject_key=p_subject_key
    and is_effective=true;

  if not found then
    return jsonb_build_object('standing','DNR','reason','owner_envpac_required');
  end if;

  v_authorized:=p_action='AUTHORIZE';
  v_standing:=case when v_authorized then 'AUTHORIZED' else 'REVOKED' end;

  update public.c3_pac
  set metadata=jsonb_set(
        coalesce(metadata,'{}'::jsonb),
        '{encounter_projection}',
        jsonb_build_object(
          'standing',v_standing,
          'encounter_key',p_encounter_key,
          'projection_surface','c2ME_env',
          'owner_authorization_required',true,
          'authorized_by_owner',v_authorized,
          'owner_subject_key',p_subject_key,
          'authorization_surface','my_pacs',
          'presentation_scope',case when v_authorized then p_surface_scope else 'none' end,
          'surface_projections',case
            when not v_authorized then '[]'::jsonb
            when p_surface_scope='c3field_plus_canopy'
              then jsonb_build_array('c3field','canopy')
            else jsonb_build_array('c3field')
          end,
          'authorization_snapshot_hash',case when v_authorized then v_current_hash else null end,
          'resolved_at',v_now
        ),
        true
      ),
      updated_at=v_now
  where pac_key=p_pac_key;

  v_host:=nullif(v_pac.metadata->>'canonical_host','');
  if v_host is null then
    v_host:=nullif(v_pac.metadata#>>'{public_presentation,canonical_host}','');
  end if;
  if v_host is not null then v_url:='https://'||v_host||'/'; end if;

  select reference_key into v_existing_reference
  from public.c3_envpac_canopy_reference
  where envpac_key=v_pac.envpac_key
    and owner_subject_key=p_subject_key
    and metadata->>'source_pac_key'=p_pac_key
  order by created_at desc
  limit 1;

  if v_authorized and p_surface_scope='c3field_plus_canopy' and v_url is not null then
    if v_existing_reference is null then
      insert into public.c3_envpac_canopy_reference(
        reference_key,envpac_key,owner_subject_key,surface_label,display_label,
        external_url,handle,sort_order,reference_state,metadata,created_at,updated_at
      ) values (
        gen_random_uuid(),v_pac.envpac_key,p_subject_key,'c3 Field',
        coalesce(v_pac.metadata#>>'{public_presentation,title}',p_pac_key),
        v_url,
        coalesce(v_pac.metadata#>>'{public_presentation,title}',p_pac_key),
        10,'active',
        jsonb_build_object(
          'source_process','personal_pac_encounter_projection_v1',
          'selection_class','canopy_reference',
          'source_pac_key',p_pac_key,
          'encounter_key',p_encounter_key,
          'projection_class','owner_selected_encounter_surface',
          'projection_snapshot_hash',v_current_hash,
          'custody_transfer',false,
          'owner_surface_scope','c3field_plus_canopy'
        ),
        v_now,v_now
      );
    else
      update public.c3_envpac_canopy_reference
      set reference_state='active',
          removed_at=null,
          external_url=v_url,
          metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
            'projection_class','owner_selected_encounter_surface',
            'projection_snapshot_hash',v_current_hash,
            'owner_surface_scope','c3field_plus_canopy',
            'custody_transfer',false
          ),
          updated_at=v_now
      where reference_key=v_existing_reference;
    end if;
  elsif v_existing_reference is not null then
    update public.c3_envpac_canopy_reference
    set reference_state='removed',
        removed_at=v_now,
        metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
          'removed_by_owner_surface_scope',true,
          'owner_surface_scope',case when v_authorized then 'c3field_only' else 'none' end
        ),
        updated_at=v_now
    where reference_key=v_existing_reference
      and reference_state<>'removed';
  end if;

  return jsonb_build_object(
    'standing',case when v_authorized then 'ACT' else 'HLD' end,
    'pac_key',p_pac_key,
    'encounter_projection_standing',v_standing,
    'encounter_key',p_encounter_key,
    'authorized_by_owner',v_authorized,
    'presentation_scope',case when v_authorized then p_surface_scope else 'none' end,
    'surface_projections',case
      when not v_authorized then '[]'::jsonb
      when p_surface_scope='c3field_plus_canopy' then jsonb_build_array('c3field','canopy')
      else jsonb_build_array('c3field')
    end,
    'authorization_snapshot_hash',case when v_authorized then v_current_hash else null end,
    'resolved_at',v_now
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.c3_validate_current_accrual_v1(p_subject_type text, p_subject_key text, p_env_key text, p_envpac_key text, p_current_state_key text, p_source_class text, p_source_key text, p_source_pac_key text, p_relation_standing text, p_evidence_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_state public.c3_current_state%rowtype;
  v_current_count integer;
  v_pac public.c3_pac%rowtype;
  v_receipt public.c3_pac_registration_receipt%rowtype;
  v_binding_count integer;
  v_envpac_count integer;
  v_bound_envpac text;
  v_relation_key text;
  v_event_key text;
  v_conn public.c3_env_native_connection%rowtype;
  v_vis public.c3_env_initiative_visibility%rowtype;
  v_expected_standing text;
begin
  if nullif(btrim(coalesce(p_current_state_key,'')),'') is null then
    return jsonb_build_object('standing','HLD','reason','current_state_required');
  end if;
  if nullif(btrim(coalesce(p_evidence_ref,'')),'') is null then
    return jsonb_build_object('standing','HLD','reason','current_evidence_ref_required');
  end if;
  if nullif(btrim(coalesce(p_env_key,'')),'') is null
     or nullif(btrim(coalesce(p_subject_key,'')),'') is null
     or nullif(btrim(coalesce(p_source_key,'')),'') is null then
    return jsonb_build_object('standing','HLD','reason','current_accrual_input_incomplete');
  end if;

  if not exists(
    select 1 from public.c3_environment
    where env_key=p_env_key and is_active=true
  ) then
    return jsonb_build_object('standing','HLD','reason','current_environment_unresolved');
  end if;

  select * into v_state
  from public.c3_current_state
  where current_state_key=p_current_state_key
    and env_key=p_env_key;

  if not found then
    return jsonb_build_object('standing','HLD','reason','current_state_lineage_unresolved');
  end if;

  if not v_state.is_current or v_state.superseded_at is not null then
    return jsonb_build_object('standing','HLD','reason','current_state_not_current');
  end if;

  if v_state.effective_at>now() then
    return jsonb_build_object('standing','HLD','reason','current_state_not_effective');
  end if;

  select count(*) into v_current_count
  from public.c3_current_state
  where env_key=p_env_key
    and is_current=true
    and superseded_at is null
    and effective_at<=now();

  if v_current_count<>1 then
    return jsonb_build_object(
      'standing','HLD','reason','current_state_current_ambiguous','count',v_current_count
    );
  end if;

  if p_envpac_key is not null and not exists(
    select 1 from public.c3_envpac
    where envpac_key=p_envpac_key
      and env_key=p_env_key
      and is_effective=true
  ) then
    return jsonb_build_object('standing','HLD','reason','current_envpac_unresolved');
  end if;

  if p_subject_type='individual' and not exists(
    select 1 from public.crs_relationship
    where relationship_key=p_subject_key
      and is_active=true
      and coalesce(is_test_relationship,false)=false
  ) then
    return jsonb_build_object('standing','HLD','reason','current_individual_relation_unresolved');
  end if;

  if p_source_class='state' then
    if p_subject_type<>'environment'
       or p_subject_key<>p_env_key
       or p_source_pac_key is not null
       or p_relation_standing<>'current' then
      return jsonb_build_object('standing','HLD','reason','current_state_source_mismatch');
    end if;

    if v_state.state_version=1 then
      if p_source_key is distinct from 'bind:'||v_state.current_state_key
         or p_evidence_ref is distinct from v_state.formation_authority_ref then
        return jsonb_build_object('standing','HLD','reason','current_state_source_mismatch');
      end if;
    else
      if p_source_key is distinct from 'advance:'||v_state.current_state_key
         or p_evidence_ref is distinct from v_state.advance_disposition_ref then
        return jsonb_build_object('standing','HLD','reason','current_state_source_mismatch');
      end if;
    end if;

    return jsonb_build_object(
      'standing','PASS','source_class','state',
      'current_state_key',v_state.current_state_key
    );
  end if;

  if p_source_class='pac' then
    if p_source_pac_key is null then
      return jsonb_build_object('standing','HLD','reason','current_source_pac_required');
    end if;

    select * into v_pac
    from public.c3_pac
    where pac_key=p_source_pac_key
      and is_effective=true
      and registration_protocol='registrar_v1';

    if not found then
      return jsonb_build_object('standing','HLD','reason','current_source_pac_unresolved');
    end if;

    if v_pac.owner_subject_type is distinct from p_subject_type
       or v_pac.owner_subject_key is distinct from p_subject_key then
      return jsonb_build_object('standing','HLD','reason','current_source_pac_owner_mismatch');
    end if;

    select count(*) into v_binding_count
    from public.c3_pac_model_binding b
    where b.pac_key=v_pac.pac_key
      and b.env_key=p_env_key
      and b.standing='active'
      and p_source_key='pac_registration:'||v_pac.pac_key||':'||b.circuit_key;

    if v_binding_count<>1 then
      return jsonb_build_object(
        'standing','HLD','reason','current_source_pac_binding_unresolved','count',v_binding_count
      );
    end if;

    select * into v_receipt
    from public.c3_pac_registration_receipt
    where pac_key=v_pac.pac_key
      and standing='registered';

    if not found
       or v_receipt.registration_sha256 is distinct from v_pac.registration_sha256
       or p_evidence_ref is distinct from 'pac_registration:'||v_receipt.registration_key then
      return jsonb_build_object('standing','HLD','reason','current_source_pac_receipt_unresolved');
    end if;

    if p_relation_standing<>'registered' then
      return jsonb_build_object('standing','HLD','reason','current_source_pac_standing_mismatch');
    end if;

    select count(*),min(envpac_key) into v_envpac_count,v_bound_envpac
    from public.c3_envpac
    where env_key=p_env_key
      and is_effective=true;

    if v_envpac_count<>1
       or p_envpac_key is null
       or p_envpac_key is distinct from v_bound_envpac then
      return jsonb_build_object(
        'standing','HLD','reason','current_bound_envpac_unresolved',
        'count',v_envpac_count
      );
    end if;

    return jsonb_build_object(
      'standing','PASS','source_class','pac',
      'source_pac_key',v_pac.pac_key,
      'bound_envpac_key',v_bound_envpac,
      'current_state_key',v_state.current_state_key
    );
  end if;

  if p_source_class='relation' then
    if p_source_pac_key is not null then
      return jsonb_build_object('standing','HLD','reason','current_relation_source_pac_unexpected');
    end if;

    if p_source_key like 'c1_relationship:%' then
      v_relation_key:=substr(p_source_key,length('c1_relationship:')+1);

      if p_subject_type<>'individual'
         or p_subject_key is distinct from v_relation_key
         or p_relation_standing<>'c1_C1_persisted'
         or p_evidence_ref not like 'crs_relationship_event:%' then
        return jsonb_build_object('standing','HLD','reason','current_c1_relation_source_mismatch');
      end if;

      v_event_key:=substr(p_evidence_ref,length('crs_relationship_event:')+1);

      if not exists(
        select 1 from public.crs_relationship r
        where r.relationship_key=v_relation_key
          and r.is_active=true
          and coalesce(r.is_test_relationship,false)=false
          and r.relationship_standing='c1_C1_persisted'
      ) then
        return jsonb_build_object('standing','HLD','reason','current_c1_relation_unresolved');
      end if;

      if p_envpac_key is null or not exists(
        select 1 from public.c3_envpac ep
        where ep.envpac_key=p_envpac_key
          and ep.env_key=p_env_key
          and ep.is_effective=true
          and ep.owner_subject_type='individual'
          and ep.owner_subject_key=v_relation_key
      ) then
        return jsonb_build_object('standing','HLD','reason','current_c1_envpac_unresolved');
      end if;

      if not exists(
        select 1 from public.crs_relationship_event e
        where e.event_key=v_event_key
          and e.relationship_key=v_relation_key
          and e.event_type='c1_relationship_persisted'
          and e.event_standing='c1_C1_persisted'
      ) then
        return jsonb_build_object('standing','HLD','reason','current_c1_evidence_unresolved');
      end if;

      return jsonb_build_object(
        'standing','PASS','source_class','relation',
        'relation_type','c1_relationship',
        'source_relation_key',v_relation_key
      );
    end if;

    if p_source_key like 'native_connection:%' then
      v_relation_key:=substr(p_source_key,length('native_connection:')+1);

      select * into v_conn
      from public.c3_env_native_connection
      where connection_key=v_relation_key;

      if not found then
        return jsonb_build_object('standing','HLD','reason','current_native_connection_unresolved');
      end if;

      if p_subject_type<>'individual'
         or p_envpac_key is null
         or not (
           (
             v_conn.source_relationship_key=p_subject_key
             and v_conn.source_env_key=p_env_key
             and v_conn.source_envpac_key=p_envpac_key
           )
           or
           (
             v_conn.target_relationship_key=p_subject_key
             and v_conn.target_env_key=p_env_key
             and v_conn.target_envpac_key=p_envpac_key
           )
         ) then
        return jsonb_build_object('standing','HLD','reason','current_native_connection_context_mismatch');
      end if;

      v_expected_standing:=case
        when v_conn.revoked_at is not null then 'revoked'
        else v_conn.standing
      end;

      if p_relation_standing is distinct from v_expected_standing
         or p_evidence_ref is distinct from p_source_key then
        return jsonb_build_object('standing','HLD','reason','current_native_connection_evidence_mismatch');
      end if;

      return jsonb_build_object(
        'standing','PASS','source_class','relation',
        'relation_type','native_connection',
        'source_relation_key',v_relation_key
      );
    end if;

    if p_source_key like 'initiative_visibility:%' then
      v_relation_key:=substr(p_source_key,length('initiative_visibility:')+1);

      select * into v_vis
      from public.c3_env_initiative_visibility
      where visibility_key=v_relation_key;

      if not found then
        return jsonb_build_object('standing','HLD','reason','current_initiative_visibility_unresolved');
      end if;

      if p_subject_type<>'individual'
         or p_envpac_key is null
         or v_vis.relationship_key is distinct from p_subject_key
         or v_vis.env_key is distinct from p_env_key
         or v_vis.envpac_key is distinct from p_envpac_key then
        return jsonb_build_object('standing','HLD','reason','current_initiative_visibility_context_mismatch');
      end if;

      v_expected_standing:=case
        when v_vis.revoked_at is not null then 'revoked'
        else v_vis.standing
      end;

      if p_relation_standing is distinct from v_expected_standing
         or p_evidence_ref is distinct from p_source_key then
        return jsonb_build_object('standing','HLD','reason','current_initiative_visibility_evidence_mismatch');
      end if;

      return jsonb_build_object(
        'standing','PASS','source_class','relation',
        'relation_type','initiative_visibility',
        'source_relation_key',v_relation_key
      );
    end if;

    return jsonb_build_object('standing','HLD','reason','current_relation_source_unregistered');
  end if;

  if p_source_class in ('evidence','encounter','oar_return','system') then
    return jsonb_build_object('standing','HLD','reason','current_source_provenance_unregistered');
  end if;

  return jsonb_build_object('standing','HLD','reason','current_source_class_unresolved');
end $function$

CREATE OR REPLACE FUNCTION public.c3_validate_pac_supersession_v1(p_presented_pac jsonb, p_lock_prior boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_supersedes text := nullif(p_presented_pac->>'supersedes_pac_key','');
  v_new_pac_key text := nullif(p_presented_pac->>'pac_key','');
  v_prior public.c3_pac%rowtype;
  v_prior_env_key text;
  v_new_env_key text;
  v_new_effective boolean;
  v_successor_count integer;
begin
  if v_supersedes is null then
    return jsonb_build_object(
      'standing','PASS',
      'supersession_requested',false
    );
  end if;

  if v_new_pac_key is not null and v_new_pac_key=v_supersedes then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_self_reference',
      'prior_pac_key',v_supersedes
    );
  end if;

  if p_presented_pac ? 'is_effective'
     and jsonb_typeof(p_presented_pac->'is_effective') is distinct from 'boolean' then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_new_pac_must_be_effective',
      'prior_pac_key',v_supersedes
    );
  end if;

  v_new_effective:=coalesce((p_presented_pac->>'is_effective')::boolean,true);
  if not v_new_effective then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_new_pac_must_be_effective',
      'prior_pac_key',v_supersedes
    );
  end if;

  if p_lock_prior then
    select * into v_prior
    from public.c3_pac
    where pac_key=v_supersedes
    for update;
  else
    select * into v_prior
    from public.c3_pac
    where pac_key=v_supersedes;
  end if;

  if not found then
    return jsonb_build_object(
      'standing','HLD',
      'reason','superseded_pac_unresolved',
      'prior_pac_key',v_supersedes
    );
  end if;

  if v_prior.registration_protocol is distinct from 'registrar_v1' then
    return jsonb_build_object(
      'standing','HLD',
      'reason','superseded_pac_not_hardened',
      'prior_pac_key',v_supersedes
    );
  end if;

  select count(*) into v_successor_count
  from public.c3_pac p
  where p.supersedes_pac_key=v_prior.pac_key
    and p.registration_protocol='registrar_v1'
    and p.is_effective=true
    and p.superseded_at is null
    and p.pac_key is distinct from v_new_pac_key;

  if v_successor_count>0 then
    return jsonb_build_object(
      'standing','HLD',
      'reason','superseded_pac_already_replaced',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  if not v_prior.is_effective or v_prior.superseded_at is not null then
    return jsonb_build_object(
      'standing','HLD',
      'reason','superseded_pac_not_effective',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  if v_prior.pac_type is distinct from p_presented_pac->>'pac_type' then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_pac_type_mismatch',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  if v_prior.owner_subject_type is distinct from p_presented_pac->>'owner_subject_type'
     or v_prior.owner_subject_key is distinct from p_presented_pac->>'owner_subject_key' then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_owner_mismatch',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  if v_prior.owner_environment_key is distinct from nullif(p_presented_pac->>'owner_environment_key','') then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_owner_environment_mismatch',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  select env_key into v_prior_env_key
  from public.c3_envpac
  where envpac_key=v_prior.envpac_key;

  select env_key into v_new_env_key
  from public.c3_envpac
  where envpac_key=p_presented_pac->>'envpac_key'
    and is_effective=true;

  if v_prior_env_key is null or v_new_env_key is null then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_environment_unresolved',
      'prior_pac_key',v_prior.pac_key
    );
  end if;

  if v_prior_env_key is distinct from v_new_env_key then
    return jsonb_build_object(
      'standing','HLD',
      'reason','supersession_environment_mismatch',
      'prior_pac_key',v_prior.pac_key,
      'prior_env_key',v_prior_env_key,
      'new_env_key',v_new_env_key
    );
  end if;

  return jsonb_build_object(
    'standing','PASS',
    'supersession_requested',true,
    'prior_pac_key',v_prior.pac_key,
    'env_key',v_prior_env_key,
    'owner_subject_type',v_prior.owner_subject_type,
    'owner_subject_key',v_prior.owner_subject_key
  );
end $function$

CREATE OR REPLACE FUNCTION public.form_profile_pac_v1_internal(p_envpac_key text, p_subject_type text, p_subject_key text, p_profile_class text, p_display_label text, p_visibility_scope text DEFAULT 'private'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_envpac public.c3_envpac%rowtype;
  v_existing jsonb;
  v_pac_key text;
  v_profile_key text;
  v_eval jsonb;
  v_source_authority text;
begin
  if p_envpac_key is null or p_subject_type is null or p_subject_key is null then
    raise exception 'profile_identity_required';
  end if;

  select * into v_envpac
  from public.c3_envpac
  where envpac_key=p_envpac_key and is_effective=true;
  if not found then raise exception 'envpac_not_effective'; end if;

  if v_envpac.owner_subject_type<>p_subject_type or v_envpac.owner_subject_key<>p_subject_key then
    raise exception 'profile_subject_not_envpac_owner';
  end if;

  if p_profile_class not in ('individual','organization','initiative','project','place') then
    raise exception 'profile_class_invalid';
  end if;
  if p_subject_type='individual' and p_profile_class<>'individual' then
    raise exception 'profile_class_subject_mismatch';
  end if;
  if p_subject_type<>'individual' and p_profile_class='individual' then
    raise exception 'profile_class_subject_mismatch';
  end if;

  if p_display_label is null or length(btrim(p_display_label))<1 or length(btrim(p_display_label))>160 then
    raise exception 'display_label_invalid';
  end if;
  if p_visibility_scope not in ('private','environment','relational','public') then
    raise exception 'visibility_scope_invalid';
  end if;

  select source_authority into v_source_authority
  from public.c3_pac_type_contract
  where contract_key='pac_contract_profilepac_v1'
    and pac_type='ProfilePAC'
    and standing='active'
    and is_effective=true;

  if v_source_authority is null then
    raise exception 'profile_contract_unavailable';
  end if;

  v_existing:=public.resolve_profile_pac_v1_internal(p_envpac_key,p_subject_type,p_subject_key);
  if coalesce(v_existing->>'standing','')<>'profile_not_formed' then
    return jsonb_build_object('ok',true,'created',false,'truth',v_existing);
  end if;

  v_profile_key:='profile_'||substr(md5(p_envpac_key||':'||p_subject_type||':'||p_subject_key),1,24);
  v_pac_key:='profile_pac_'||substr(md5(p_envpac_key||':'||p_subject_type||':'||p_subject_key),1,24)||'_v1';

  insert into public.c3_pac (
    pac_key,envpac_key,pac_type,version,standing,custody_uri,source_authority,is_effective,metadata,
    contract_key,architecture_version,custodian_subject_type,custodian_subject_key,custody_provider,
    authority_effect,release_state,execution_authority_state,formation_state,effective_at,
    return_evidence_required
  ) values (
    v_pac_key,p_envpac_key,'ProfilePAC','v1','registered_complete_profile_ready',
    'c3://profile-pac/'||v_profile_key||'/v1',
    v_source_authority,true,
    jsonb_build_object(
      'formation_route','oye_profilepac_v1',
      'profile_does_not_create_authority',true,
      'subject_values_explicitly_submitted',true,
      'ownership_model',jsonb_build_object(
        'owner_subject_type',p_subject_type,
        'owner_subject_key',p_subject_key,
        'ownership_class','personal_subject_pac'
      ),
      'custody_model',jsonb_build_object(
        'custody_class','personal_pac_custody',
        'custody_surface','my_pacs',
        'custodian_subject_type',p_subject_type,
        'custodian_subject_key',p_subject_key,
        'envpac_role','resolution_only',
        'approval_surface','my_pacs',
        'c2me_role','approved_pac_projection_only'
      )
    ),
    'pac_contract_profilepac_v1','pac_v1',
    p_subject_type,p_subject_key,'c3_field',
    'none',p_visibility_scope,'none','formed',now(),false
  );

  insert into public.c3_profile_pac (
    pac_key,profile_key,subject_type,subject_key,profile_class,display_label,visibility_scope,metadata
  ) values (
    v_pac_key,v_profile_key,p_subject_type,p_subject_key,p_profile_class,btrim(p_display_label),p_visibility_scope,
    '{"authority_effect":"none","source":"oye_explicit_intake"}'::jsonb
  );

  v_eval:=public.c3_pac_evaluate(v_pac_key);
  if coalesce(v_eval->>'completeness_state','held')<>'pass' then
    raise exception 'profile_pac_incomplete';
  end if;

  return jsonb_build_object('ok',true,'created',true,'truth',public.c3_profile_pac_truth(v_pac_key));
end;
$function$

CREATE OR REPLACE FUNCTION public.free_resolve_pac_encounter_v1(p_free_call_key text, p_selector_type text, p_selector_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_call public.c3_free_call%rowtype;
  v_snapshot public.c3_free_pac_snapshot%rowtype;
  v_pac public.c3_pac%rowtype;
  v_count integer;
  v_projection_sha text;
  v_trace jsonb;
  v_binding_count integer;
  v_current_count integer;
  v_envpac_gap_count integer;
  v_accrual_gap_count integer;
begin
  select * into v_call
  from public.c3_free_call
  where free_call_key=p_free_call_key
    and standing='active'
    and requires_pac_snapshot=true
    and surface_class<>'my_env';

  if not found then
    return jsonb_build_object('standing','DNR','reason','free_call_not_registered','free_call_key',p_free_call_key);
  end if;

  if p_selector_type not in ('host','route','encounter','none') then
    return jsonb_build_object('standing','DNR','reason','free_selector_invalid','free_call_key',p_free_call_key);
  end if;

  select count(*),min(free_snapshot_key) into v_count,v_projection_sha
  from public.c3_free_pac_snapshot
  where free_call_key=p_free_call_key
    and selector_type=p_selector_type
    and (
      (p_selector_type='none' and selector_value is null)
      or selector_value=p_selector_value
    )
    and standing='active';

  if v_count<>1 then
    return jsonb_build_object(
      'standing','DNR',
      'reason',case when v_count=0 then 'registered_snapshot_not_resolved' else 'registered_snapshot_collision' end,
      'free_call_key',p_free_call_key
    );
  end if;

  select * into v_snapshot
  from public.c3_free_pac_snapshot
  where free_snapshot_key=v_projection_sha;

  select * into v_pac
  from public.c3_pac
  where pac_key=v_snapshot.pac_key
    and is_effective=true
    and registration_protocol='registrar_v1';

  if not found then
    return jsonb_build_object('standing','DNR','reason','registered_pac_not_effective','free_call_key',p_free_call_key);
  end if;

  if v_pac.schema_key is distinct from v_snapshot.schema_key
     or v_pac.registration_sha256 is distinct from v_snapshot.registration_sha256 then
    return jsonb_build_object('standing','DNR','reason','registered_pac_identity_mismatch','pac_key',v_pac.pac_key);
  end if;

  if not exists(
    select 1 from public.c3_pac_schema
    where schema_key=v_pac.schema_key and pac_type=v_pac.pac_type and standing='active' and is_active=true
  ) then
    return jsonb_build_object('standing','DNR','reason','pac_schema_not_resolved','pac_key',v_pac.pac_key);
  end if;

  if not exists(
    select 1 from public.c3_pac_encounter_scope s
    where s.pac_key=v_pac.pac_key
      and s.free_call_key=p_free_call_key
      and s.encounter_key=v_snapshot.encounter_key
      and s.surface_type=v_snapshot.surface_type
      and s.selector_type=v_snapshot.selector_type
      and s.selector_value is not distinct from v_snapshot.selector_value
      and s.standing='active'
  ) then
    return jsonb_build_object('standing','DNR','reason','encounter_scope_not_resolved','pac_key',v_pac.pac_key);
  end if;

  v_projection_sha:=encode(
    extensions.digest(convert_to(v_snapshot.projection::text,'UTF8'),'sha256'),
    'hex'
  );
  if v_projection_sha<>v_snapshot.projection_sha256 then
    return jsonb_build_object('standing','DNR','reason','registered_projection_integrity_mismatch','pac_key',v_pac.pac_key);
  end if;

  select count(*) into v_binding_count
  from public.c3_pac_model_binding b
  where b.pac_key=v_pac.pac_key and b.standing='active';

  if coalesce((select requires_c3_model_binding from public.c3_pac_schema where schema_key=v_pac.schema_key),true)
     and v_binding_count=0 then
    return jsonb_build_object('standing','DNR','reason','c3_model_binding_not_resolved','pac_key',v_pac.pac_key);
  end if;

  select count(*) into v_current_count
  from public.c3_pac_model_binding b
  where b.pac_key=v_pac.pac_key
    and b.standing='active'
    and (
      select count(*) from public.c3_current_state cs
      where cs.env_key=b.env_key
        and cs.is_current=true
        and cs.superseded_at is null
        and cs.effective_at<=now()
    )<>1;

  if v_current_count>0 then
    return jsonb_build_object('standing','DNR','reason','ACT_current_trace_not_resolved','pac_key',v_pac.pac_key);
  end if;

  select count(*) into v_envpac_gap_count
  from public.c3_pac_model_binding b
  where b.pac_key=v_pac.pac_key
    and b.standing='active'
    and (
      select count(*) from public.c3_envpac ep
      where ep.env_key=b.env_key and ep.is_effective=true
    )<>1;

  if v_envpac_gap_count>0 then
    return jsonb_build_object('standing','DNR','reason','ACT_envpac_trace_not_resolved','pac_key',v_pac.pac_key);
  end if;

  select count(*) into v_accrual_gap_count
  from public.c3_pac_model_binding b
  join public.c3_current_state cs
    on cs.env_key=b.env_key
   and cs.is_current=true
   and cs.superseded_at is null
   and cs.effective_at<=now()
  where b.pac_key=v_pac.pac_key
    and b.standing='active'
    and not exists(
      select 1
      from public.c3_current_accrual ca
      join public.c3_pac_registration_receipt rr
        on rr.pac_key=v_pac.pac_key
       and rr.standing='registered'
       and rr.registration_sha256=v_pac.registration_sha256
      join public.c3_envpac ep
        on ep.envpac_key=ca.envpac_key
       and ep.env_key=b.env_key
       and ep.is_effective=true
      where ca.env_key=b.env_key
        and ca.current_state_key=cs.current_state_key
        and ca.source_class='pac'
        and ca.source_pac_key=v_pac.pac_key
        and ca.source_key='pac_registration:'||v_pac.pac_key||':'||b.circuit_key
        and ca.subject_type=v_pac.owner_subject_type
        and ca.subject_key=v_pac.owner_subject_key
        and ca.relation_standing='registered'
        and ca.evidence_ref='pac_registration:'||rr.registration_key
    );

  if v_accrual_gap_count>0 then
    return jsonb_build_object(
      'standing','DNR','reason','ACT_CURRENT_accrual_not_resolved','pac_key',v_pac.pac_key
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'circuit_key',b.circuit_key,
    'relation_role',b.relation_role,
    'env_key',b.env_key,
    'bound_envpac_key',(
      select min(ep.envpac_key) from public.c3_envpac ep
      where ep.env_key=b.env_key and ep.is_effective=true
    ),
    'current_state_key',cs.current_state_key,
    'state_version',cs.state_version,
    'standing',cs.standing,
    'effective_at',cs.effective_at,
    'CURRENT_accrual_count',(
      select count(*)
      from public.c3_current_accrual ca
      join public.c3_pac_registration_receipt rr
        on rr.pac_key=v_pac.pac_key
       and rr.standing='registered'
       and rr.registration_sha256=v_pac.registration_sha256
      join public.c3_envpac ep
        on ep.envpac_key=ca.envpac_key
       and ep.env_key=b.env_key
       and ep.is_effective=true
      where ca.env_key=b.env_key
        and ca.current_state_key=cs.current_state_key
        and ca.source_class='pac'
        and ca.source_pac_key=v_pac.pac_key
        and ca.source_key='pac_registration:'||v_pac.pac_key||':'||b.circuit_key
        and ca.subject_type=v_pac.owner_subject_type
        and ca.subject_key=v_pac.owner_subject_key
        and ca.relation_standing='registered'
        and ca.evidence_ref='pac_registration:'||rr.registration_key
    )
  ) order by b.circuit_key,b.env_key),'[]'::jsonb)
  into v_trace
  from public.c3_pac_model_binding b
  join public.c3_current_state cs
    on cs.env_key=b.env_key
   and cs.is_current=true
   and cs.superseded_at is null
   and cs.effective_at<=now()
  where b.pac_key=v_pac.pac_key and b.standing='active';

  return jsonb_build_object(
    'standing','ACT',
    'free_call_key',p_free_call_key,
    'pac_key',v_pac.pac_key,
    'schema_key',v_pac.schema_key,
    'registration_sha256',v_pac.registration_sha256,
    'projection_sha256',v_snapshot.projection_sha256,
    'registered_at',v_snapshot.registered_at,
    'encounter_key',v_snapshot.encounter_key,
    'surface_type',v_snapshot.surface_type,
    'ACT',v_trace,
    'snapshot',v_snapshot.projection
  );
end $function$

CREATE OR REPLACE FUNCTION public.preflight_c3ops_nug_spec_v1(p_nug_key text, p_spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_missing text[] := '{}';
  v_cap public.c3_envpac_capability_grant%rowtype;
  v_q public.system_oar_queue%rowtype;
  v_context public.c3ops_cancom_context_binding%rowtype;
  v_fn oid; v_tuple jsonb; v_effect jsonb;
begin
  if jsonb_typeof(p_spec) is distinct from 'object' or nullif(btrim(p_nug_key),'') is null then
    return jsonb_build_object('standing','HLD','missing_predicates',jsonb_build_array('binding_shape'));
  end if;
  if not exists(select 1 from public.system_process_registry where
    process_key='c3ops_nugs_native_universal_general_services_v1' and process_status='active') then
    v_missing := array_append(v_missing,'service');
  end if;
  if not exists(select 1 from public.system_process_registry where
    process_key=p_spec->>'native_process_key' and process_status='active') then
    v_missing := array_append(v_missing,'native_process');
  end if;
  -- Minimum adapter ABI: existing native public function(jsonb) -> jsonb.
  -- Pin the catalog definition so a changed body requires renewed admission.
  if coalesce(p_spec->>'native_function_ref','') ~ '^public\.[a-z][a-z0-9_]*\(jsonb\)$' then
    v_fn := to_regprocedure(p_spec->>'native_function_ref');
  end if;
  if v_fn is null or not exists(select 1 from pg_catalog.pg_proc where oid=v_fn
    and prorettype='jsonb'::regtype and not prosecdef and not proretset
    and encode(extensions.digest(pg_catalog.pg_get_functiondef(oid),'sha256'),'hex')=p_spec->>'native_function_sha256') then
    v_missing := array_append(v_missing,'native_function');
  end if;
  if not exists(select 1 from public.c3_environment where env_key=p_spec->>'origin_env_key' and is_active)
    or not exists(select 1 from public.c3_environment where env_key=p_spec->>'env_key' and is_active)
    or p_spec->>'origin_env_key' is not distinct from p_spec->>'env_key'
    or not exists(select 1 from public.c3_envpac where envpac_key=p_spec->>'envpac_key'
      and env_key=p_spec->>'env_key' and is_effective)
    or not exists(select 1 from public.c3_current_state where current_state_key=p_spec->>'current_state_key'
      and env_key=p_spec->>'env_key' and is_current and superseded_at is null) then
    v_missing := array_append(v_missing,'environment_current');
  end if;
  v_tuple := jsonb_build_object('nug_key',p_nug_key,'native_process_key',p_spec->>'native_process_key',
    'native_function_ref',p_spec->>'native_function_ref','native_function_sha256',p_spec->>'native_function_sha256',
    'origin_env_key',p_spec->>'origin_env_key','env_key',p_spec->>'env_key',
    'envpac_key',p_spec->>'envpac_key','current_state_key',p_spec->>'current_state_key',
    'executor_ref',p_spec->>'executor_ref','execution_instance',p_spec->>'execution_instance',
    'context_binding_key',p_spec->>'context_binding_key','adapter_class',p_spec->>'adapter_class',
    'adapter_process_key',p_spec->>'adapter_process_key','effect_class',p_spec->>'effect_class',
    'native_input',p_spec->'native_input','native_result_standing',p_spec->>'native_result_standing',
    'evidence_return_relation',p_spec->>'evidence_return_relation');
  select * into v_cap from public.c3_envpac_capability_grant where capability_key=p_spec->>'capability_ref';
  if v_cap.standing is distinct from 'active' or v_cap.envpac_key is distinct from p_spec->>'envpac_key'
    or not coalesce(v_cap.scope->'allowed_actions' ? 'call_nug',false)
    or not coalesce(v_cap.scope->'nug_bindings' @> jsonb_build_array(v_tuple),false) then
    v_missing := array_append(v_missing,'capability');
  end if;
  select * into v_q from public.system_oar_queue where oar_key=p_spec->>'authority_oar_key'
    and scope_key=p_spec->>'execution_instance';
  if (select count(*) from public.system_oar_queue where oar_key=p_spec->>'authority_oar_key'
      and scope_key=p_spec->>'execution_instance') <> 1
    or v_q.queue_status is null or v_q.queue_status not in ('approved_for_execution','executing')
    or v_q.operator_confirmed_at is null or v_q.preflight_status is distinct from 'passed'
    or v_q.automation_permissions->>'executor_ref' is distinct from p_spec->>'executor_ref'
    or v_q.automation_permissions->>'capability_ref' is distinct from v_cap.capability_key
    or not coalesce(v_q.automation_permissions->'nug_bindings' @> jsonb_build_array(v_tuple),false) then
    v_missing := array_append(v_missing,'authority');
  end if;
  select * into v_context from public.c3ops_cancom_context_binding
    where binding_key=p_spec->>'context_binding_key';
  if v_context.standing is distinct from 'active' or v_context.operator_confirmed_at is null
    or v_context.origin_environment is distinct from p_spec->>'origin_env_key'
    or v_context.receiving_environment is distinct from p_spec->>'env_key'
    or v_context.resolved_actor is distinct from p_spec->>'executor_ref'
    or v_context.capability_ref is distinct from v_cap.capability_key
    or v_context.source_authority_ref is distinct from 'registry://cancom/oar2/'||(p_spec->>'authority_oar_key')
    or v_context.transport_adapter is distinct from 'registry_cancom_internal'
    or v_context.payload_custody_class not in ('registry_custody_ref','none')
    or jsonb_typeof(p_spec->'native_input') is distinct from 'object'
    or nullif(p_spec->>'native_result_standing','') is null
    or p_spec->>'native_result_standing' in ('HLD','held','DNR') then
    v_missing := array_append(v_missing,'context');
  end if;
  if p_spec->>'adapter_class' = 'direct_native' then
    if p_spec->>'effect_class' is distinct from 'none'
      or not exists(select 1 from pg_catalog.pg_proc where oid=v_fn and provolatile in ('s','i'))
      or nullif(p_spec->>'adapter_process_key','') is not null then
      v_missing := array_append(v_missing,'adapter_boundary');
    end if;
  elsif p_spec->>'adapter_class' = 'registered_adapter' then
    if not exists(select 1 from public.system_process_registry where
      process_key=p_spec->>'adapter_process_key' and process_status='active'
      and metadata->>'infrastructure_class' in ('worker','provider_adapter','runtime_adapter')
      and metadata->'native_function_refs' ? (p_spec->>'native_function_ref')) then
      v_missing := array_append(v_missing,'registered_adapter');
    end if;
  else
    v_missing := array_append(v_missing,'adapter_class');
  end if;
  if nullif(p_spec->>'effect_class','') is null then
    v_missing := array_append(v_missing,'effect_preflight');
  elsif p_spec->>'effect_class' <> 'none' then
    v_effect := jsonb_build_object('binding',v_tuple,'effect_class',p_spec->>'effect_class',
      'current_state_key',p_spec->>'current_state_key','context_binding_key',p_spec->>'context_binding_key');
    if v_cap.scope->'external_provider_effects_authorized' is distinct from 'true'::jsonb
      or v_q.automation_permissions->'external_provider_effects_authorized' is distinct from 'true'::jsonb
      or (p_spec->>'effect_class' = 'external_email' and (
        v_cap.scope->'external_correspondence_authorized' is distinct from 'true'::jsonb
        or v_q.automation_permissions->'external_correspondence' is distinct from 'true'::jsonb))
      or not coalesce(v_cap.scope->'effect_preflights' @> jsonb_build_array(v_effect),false)
      or not coalesce(v_q.automation_permissions->'effect_preflights' @> jsonb_build_array(v_effect),false) then
      v_missing := array_append(v_missing,'effect_preflight');
    end if;
  end if;
  if p_spec->>'evidence_return_relation' is distinct from
    'registry://c3_current_evidence_ref/'||(p_spec->>'current_state_key') then
    v_missing := array_append(v_missing,'evidence_return');
  end if;
  if not exists(select 1 from public.system_process_registry where process_key='aop_006_free_binding'
    and process_status='active') then v_missing := array_append(v_missing,'free_resolver'); end if;
  return jsonb_build_object('standing',case when cardinality(v_missing)=0 then 'resolved_for_nug' else 'HLD' end,
    'missing_predicates',to_jsonb(v_missing),'nug_key',p_nug_key,'binding',v_tuple,
    'authority_oar_key',p_spec->>'authority_oar_key','capability_ref',p_spec->>'capability_ref',
    'authority_created',false,'custody_transferred',false,'ownership_transferred',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_register_pac_v1(p_presented_pac jsonb, p_boundary_evaluation_key text, p_registrar_role_call_key text, p_source_oar2_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_sup jsonb;
  v_sha text;
  v_pac_key text;
  v_existing public.c3_pac%rowtype;
  v_receipt public.c3_pac_registration_receipt%rowtype;
begin
  if p_presented_pac is null or jsonb_typeof(p_presented_pac)<>'object' then
    return public.registrar_register_pac_v1_core(
      p_presented_pac,p_boundary_evaluation_key,p_registrar_role_call_key,p_source_oar2_ref
    );
  end if;

  v_pac_key:=nullif(p_presented_pac->>'pac_key','');
  v_sha:=encode(extensions.digest(convert_to(p_presented_pac::text,'UTF8'),'sha256'),'hex');

  if v_pac_key is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('c3_pac_registration_key|'||v_pac_key,0)
    );
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('c3_pac_registration_sha|'||v_sha,0)
    );

    select * into v_existing
    from public.c3_pac
    where pac_key=v_pac_key
    for update;

    if found then
      if v_existing.registration_protocol is distinct from 'registrar_v1'
         or v_existing.registration_sha256 is distinct from v_sha then
        return jsonb_build_object(
          'standing','HLD',
          'reason','pac_key_non_repetition_conflict',
          'pac_key',v_pac_key
        );
      end if;

      select * into v_receipt
      from public.c3_pac_registration_receipt
      where pac_key=v_pac_key;

      if not found
         or v_receipt.registration_sha256 is distinct from v_sha
         or v_receipt.registration_key is distinct from
              'pac_registration_'||replace(v_pac_key,':','_') then
        return jsonb_build_object(
          'standing','HLD',
          'reason','registration_receipt_unresolved',
          'pac_key',v_pac_key
        );
      end if;

      if v_receipt.boundary_evaluation_key is distinct from p_boundary_evaluation_key
         or v_receipt.registrar_role_call_key is distinct from p_registrar_role_call_key
         or v_receipt.source_oar2_ref is distinct from p_source_oar2_ref then
        return jsonb_build_object(
          'standing','HLD',
          'reason','registration_retry_context_conflict',
          'pac_key',v_pac_key,
          'registration_key',v_receipt.registration_key
        );
      end if;

      return jsonb_build_object(
        'standing','REGISTERED',
        'pac_key',v_existing.pac_key,
        'registration_key',v_receipt.registration_key,
        'registration_sha256',v_sha,
        'boundary_evaluation_key',v_receipt.boundary_evaluation_key,
        'registrar_role_call_key',v_receipt.registrar_role_call_key,
        'registered_at',v_existing.registered_at,
        'idempotent',true,
        'authority_created',false,
        'ownership_transferred',false
      );
    end if;
  end if;

  v_sup:=public.c3_validate_pac_supersession_v1(p_presented_pac,true);

  if coalesce(v_sup->>'standing','HLD')<>'PASS' then
    return jsonb_build_object(
      'standing','HLD',
      'reason',coalesce(v_sup->>'reason','supersession_unresolved'),
      'prior_pac_key',v_sup->>'prior_pac_key'
    );
  end if;

  return public.registrar_register_pac_v1_core(
    p_presented_pac,
    p_boundary_evaluation_key,
    p_registrar_role_call_key,
    p_source_oar2_ref
  );
end $function$

CREATE OR REPLACE FUNCTION public.registrar_register_pac_v1_core(p_presented_pac jsonb, p_boundary_evaluation_key text, p_registrar_role_call_key text, p_source_oar2_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
declare
  v_eval public.c3_pac_boundary_evaluation%rowtype;
  v_call public.c3_ci_role_call%rowtype;
  v_sha text;
  v_pac_key text;
  v_existing public.c3_pac%rowtype;
  v_item jsonb;
  v_member_key text;
  v_registration_key text;
  v_supersedes text;
  v_owner_type text;
  v_owner_key text;
  v_owner_env text;
begin
  if p_presented_pac is null or jsonb_typeof(p_presented_pac)<>'object'
     or nullif(btrim(coalesce(p_boundary_evaluation_key,'')),'') is null
     or nullif(btrim(coalesce(p_registrar_role_call_key,'')),'') is null
     or nullif(btrim(coalesce(p_source_oar2_ref,'')),'') is null then
    return jsonb_build_object('standing','HLD','reason','registrar_input_incomplete');
  end if;

  v_sha:=encode(extensions.digest(convert_to(p_presented_pac::text,'UTF8'),'sha256'),'hex');
  v_pac_key:=p_presented_pac->>'pac_key';
  v_owner_type:=p_presented_pac->>'owner_subject_type';
  v_owner_key:=p_presented_pac->>'owner_subject_key';
  v_owner_env:=nullif(p_presented_pac->>'owner_environment_key','');
  v_supersedes:=nullif(p_presented_pac->>'supersedes_pac_key','');

  select * into v_eval
  from public.c3_pac_boundary_evaluation
  where evaluation_key=p_boundary_evaluation_key
  for update;

  if not found
     or v_eval.notchazz_result<>'PASS'
     or v_eval.presented_pac_key is distinct from v_pac_key
     or v_eval.presented_registration_sha256 is distinct from v_sha then
    return jsonb_build_object('standing','HLD','reason','notchazz_pass_exact_match_required');
  end if;

  select * into v_call
  from public.c3_ci_role_call
  where role_call_key=p_registrar_role_call_key
  for update;

  if not found
     or v_call.call_class<>'pac_registration'
     or v_call.caller_role_key<>'c3_notchazz_boundary_v1'
     or v_call.callee_role_key<>'c3_registrar_ci_v1'
     or v_call.standing<>'OPEN'
     or v_call.boundary_evaluation_key is distinct from p_boundary_evaluation_key
     or v_call.presented_sha256 is distinct from v_sha
     or v_call.source_oar2_ref is distinct from p_source_oar2_ref then
    return jsonb_build_object('standing','HLD','reason','registrar_role_call_unresolved');
  end if;

  if not exists(
    select 1 from public.c3_pac_schema
    where schema_key=p_presented_pac->>'schema_key'
      and pac_type=p_presented_pac->>'pac_type'
      and standing='active' and is_active=true
  ) then
    return jsonb_build_object('standing','HLD','reason','active_schema_unresolved');
  end if;

  if v_owner_type='institution'
     and coalesce((public.resolve_institutional_pac_eligibility_v1(v_owner_key,v_owner_env)->>'standing'),'HLD')<>'PASS' then
    return jsonb_build_object('standing','HLD','reason','HLD_INSTITUTIONAL_SEAT_REQUIRED');
  end if;

  select * into v_existing from public.c3_pac where pac_key=v_pac_key;
  if found then
    if v_existing.registration_protocol='registrar_v1'
       and v_existing.registration_sha256=v_sha then
      return jsonb_build_object(
        'standing','REGISTERED','pac_key',v_existing.pac_key,
        'registration_sha256',v_sha,'idempotent',true
      );
    end if;
    return jsonb_build_object('standing','HLD','reason','pac_key_non_repetition_conflict','pac_key',v_pac_key);
  end if;

  if exists (
    select 1 from public.c3_pac
    where registration_protocol='registrar_v1'
      and registration_sha256=v_sha
  ) then
    return jsonb_build_object('standing','HLD','reason','duplicate_registered_pac_content');
  end if;

  if v_supersedes is not null and not exists(select 1 from public.c3_pac where pac_key=v_supersedes) then
    return jsonb_build_object('standing','HLD','reason','superseded_pac_unresolved');
  end if;

  perform set_config('c3.pac_registrar_context',p_boundary_evaluation_key,true);

  insert into public.c3_pac(
    pac_key,envpac_key,pac_type,version,standing,custody_uri,content_sha256,source_authority,is_effective,metadata,
    schema_key,contract_key,architecture_version,custodian_subject_type,custodian_subject_key,custody_provider,
    authority_effect,release_state,execution_authority_state,formation_state,effective_at,supersedes_pac_key,
    return_evidence_required,owner_subject_type,owner_subject_key,owner_environment_key,
    registration_protocol,registration_sha256,boundary_evaluation_key,registered_at,registrar_role_call_key
  ) values (
    v_pac_key,p_presented_pac->>'envpac_key',p_presented_pac->>'pac_type',p_presented_pac->>'version',
    p_presented_pac->>'standing',p_presented_pac->>'custody_uri',nullif(p_presented_pac->>'content_sha256',''),
    p_presented_pac->>'source_authority',coalesce((p_presented_pac->>'is_effective')::boolean,true),
    coalesce(p_presented_pac->'metadata','{}'::jsonb),
    p_presented_pac->>'schema_key',null,p_presented_pac->>'architecture_version',
    p_presented_pac->>'custodian_subject_type',p_presented_pac->>'custodian_subject_key',p_presented_pac->>'custody_provider',
    p_presented_pac->>'authority_effect',p_presented_pac->>'release_state',p_presented_pac->>'execution_authority_state',
    p_presented_pac->>'formation_state',coalesce(nullif(p_presented_pac->>'effective_at','')::timestamptz,now()),v_supersedes,
    (p_presented_pac->>'return_evidence_required')::boolean,
    v_owner_type,v_owner_key,v_owner_env,
    'registrar_v1',v_sha,p_boundary_evaluation_key,now(),p_registrar_role_call_key
  );

  if jsonb_typeof(p_presented_pac->'model_bindings')='array' then
    for v_item in select value from jsonb_array_elements(p_presented_pac->'model_bindings')
    loop
      insert into public.c3_pac_model_binding(
        binding_key,pac_key,circuit_key,env_key,relation_role,standing,boundary_evaluation_key
      ) values (
        gen_random_uuid()::text,v_pac_key,v_item->>'circuit_key',v_item->>'env_key',
        v_item->>'relation_role','active',p_boundary_evaluation_key
      );
    end loop;
  end if;

  for v_item in select value from jsonb_array_elements(p_presented_pac->'encounter_scopes')
  loop
    insert into public.c3_pac_encounter_scope(
      scope_key,pac_key,surface_type,encounter_key,standing,boundary_evaluation_key
    ) values (
      gen_random_uuid()::text,v_pac_key,v_item->>'surface_type',v_item->>'encounter_key','active',p_boundary_evaluation_key
    );
  end loop;

  if jsonb_typeof(coalesce(p_presented_pac->'members','[]'::jsonb))='array' then
    for v_item in select value from jsonb_array_elements(coalesce(p_presented_pac->'members','[]'::jsonb))
    loop
      v_member_key:=coalesce(nullif(v_item->>'member_key',''),gen_random_uuid()::text);
      insert into public.c3_pac_member(
        member_key,pac_key,member_kind,member_role,source_object_key,custody_provider,custody_identifier,
        custody_location,runtime_uri,runtime_binding_key,integrity_algorithm,integrity_value,version,
        standing,required,release_scope,ordinal,metadata
      ) values (
        v_member_key,v_pac_key,v_item->>'member_kind',v_item->>'member_role',
        nullif(v_item->>'source_object_key',''),nullif(v_item->>'custody_provider',''),nullif(v_item->>'custody_identifier',''),
        nullif(v_item->>'custody_location',''),nullif(v_item->>'runtime_uri',''),nullif(v_item->>'runtime_binding_key',''),
        nullif(v_item->>'integrity_algorithm',''),nullif(v_item->>'integrity_value',''),nullif(v_item->>'version',''),
        coalesce(nullif(v_item->>'standing',''),'active'),coalesce((v_item->>'required')::boolean,false),
        coalesce(nullif(v_item->>'release_scope',''),'registered'),
        nullif(v_item->>'ordinal','')::integer,coalesce(v_item->'metadata','{}'::jsonb)
      );
    end loop;
  end if;

  if jsonb_typeof(coalesce(p_presented_pac->'relations','[]'::jsonb))='array' then
    for v_item in select value from jsonb_array_elements(coalesce(p_presented_pac->'relations','[]'::jsonb))
    loop
      insert into public.c3_pac_relation(
        relation_key,source_pac_key,relation_type,target_kind,target_key,standing,metadata
      ) values (
        coalesce(nullif(v_item->>'relation_key',''),gen_random_uuid()::text),
        v_pac_key,v_item->>'relation_type',v_item->>'target_kind',v_item->>'target_key',
        coalesce(nullif(v_item->>'standing',''),'active'),coalesce(v_item->'metadata','{}'::jsonb)
      );
    end loop;
  end if;

  if p_presented_pac->>'pac_type'='ProfilePAC' then
    insert into public.c3_profile_pac(
      pac_key,profile_key,subject_type,subject_key,profile_class,display_label,visibility_scope,metadata
    ) values (
      v_pac_key,
      p_presented_pac#>>'{profile,profile_key}',
      p_presented_pac#>>'{profile,subject_type}',
      p_presented_pac#>>'{profile,subject_key}',
      p_presented_pac#>>'{profile,profile_class}',
      p_presented_pac#>>'{profile,display_label}',
      p_presented_pac#>>'{profile,visibility_scope}',
      coalesce(p_presented_pac#>'{profile,metadata}','{}'::jsonb)
    );
  end if;

  v_registration_key:='pac_registration_'||replace(v_pac_key,':','_');
  insert into public.c3_pac_registration_receipt(
    registration_key,pac_key,boundary_evaluation_key,registration_sha256,registrar_role_call_key,
    source_oar2_ref,standing
  ) values (
    v_registration_key,v_pac_key,p_boundary_evaluation_key,v_sha,p_registrar_role_call_key,
    p_source_oar2_ref,'registered'
  );

  if v_supersedes is not null then
    update public.c3_pac
    set is_effective=false,superseded_at=now(),updated_at=now()
    where pac_key=v_supersedes and is_effective=true;
  end if;

  update public.c3_ci_role_call
  set standing='RETURNED',resolved_at=now(),result_ref=v_registration_key,
      evidence=evidence||jsonb_build_object('pac_key',v_pac_key,'registration_sha256',v_sha)
  where role_call_key=p_registrar_role_call_key;

  return jsonb_build_object(
    'standing','REGISTERED','pac_key',v_pac_key,'registration_key',v_registration_key,
    'registration_sha256',v_sha,'boundary_evaluation_key',p_boundary_evaluation_key,
    'registrar_role_call_key',p_registrar_role_call_key,
    'authority_created',false,'ownership_transferred',false
  );
end $function$

CREATE OR REPLACE FUNCTION public.resolve_c1me_current_internal(p_relationship_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r public.crs_relationship%rowtype;
  v_envpac_count integer;
  v_envpac text;
  v_env text;
  v_grant_count integer;
  v_current_count integer;
  v_current text;
  v_evidence_count integer;
begin
  if p_relationship_key is null or btrim(p_relationship_key)='' then
    return jsonb_build_object('resolution','auth_required','reason_code','missing_verified_subject');
  end if;

  select * into r from public.crs_relationship
  where relationship_key=p_relationship_key
    and is_active=true
    and coalesce(is_test_relationship,false)=false;

  if not found or r.relationship_standing<>'c1_C1_persisted' then
    return jsonb_build_object('resolution','reconciliation_hold','reason_code','c1_not_persisted',
      'may_create_personal_environment',false);
  end if;

  select count(*),min(envpac_key),min(env_key)
    into v_envpac_count,v_envpac,v_env
  from public.c3_envpac
  where owner_subject_type='individual'
    and owner_subject_key=p_relationship_key
    and is_effective=true
    and standing='effective';

  if v_envpac_count<>1 then
    return jsonb_build_object('resolution','reconciliation_hold',
      'reason_code',case when v_envpac_count=0 then 'canonical_env_missing' else 'canonical_env_ambiguous' end,
      'may_create_personal_environment',false);
  end if;

  select count(*) into v_grant_count
  from public.c3_envpac_access_grant
  where envpac_key=v_envpac
    and subject_type='individual'
    and subject_key=p_relationship_key
    and relation_role='owner'
    and standing='active'
    and revoked_at is null
    and (expires_at is null or expires_at>now());

  if v_grant_count<>1 then
    return jsonb_build_object('resolution','reconciliation_hold','reason_code','owner_grant_missing_or_ambiguous',
      'may_create_personal_environment',false);
  end if;

  select count(*),min(current_state_key)
    into v_current_count,v_current
  from public.c3_current_state
  where env_key=v_env and is_current=true and effective_at<=now() and superseded_at is null;

  if v_current_count<>1 then
    return jsonb_build_object('resolution','reconciliation_hold','reason_code','personal_current_missing_or_ambiguous',
      'may_create_personal_environment',false);
  end if;

  select count(*) into v_evidence_count
  from public.c3_current_evidence_ref
  where current_state_key=v_current
    and evidence_standing in ('effective','attested','accepted','registered');

  if v_evidence_count<1 then
    return jsonb_build_object('resolution','reconciliation_hold','reason_code','current_evidence_missing',
      'may_create_personal_environment',false);
  end if;

  return jsonb_build_object(
    'resolution','existing_c1',
    'next_encounter','enter_existing_environment',
    'relationship_ref',p_relationship_key,
    'envpac_ref',v_envpac,
    'env_key',v_env,
    'current_ref',v_current,
    'may_create_personal_environment',false,
    'reason_code','resolved_from_registered_current'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_c3ops_my_stash_v1(p_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_op text; v_req jsonb; v_key text; v_item jsonb; v_asset public.c3ops_asset_record%rowtype;
  v_items jsonb; v_event jsonb; v_seq bigint; v_tags jsonb;
begin
  if jsonb_typeof(p_input) is distinct from 'object'
    or jsonb_typeof(p_input->'request') is distinct from 'object'
    or p_input->>'default_visibility' is distinct from 'private'
    or p_input->>'event_contract' is distinct from 'my_stash_private_reference_v1'
    or not exists(select 1 from public.c3_envpac e join public.c3_current_state c on c.env_key=e.env_key
      where e.envpac_key=p_input->>'envpac_key' and e.env_key=p_input->>'env_key' and e.is_effective
        and e.owner_subject_key=p_input->>'owner_subject_key'
        and c.current_state_key=p_input->>'current_state_key' and c.is_current and c.superseded_at is null)
    or not exists(select 1 from public.c3_envpac_access_grant g where
      g.envpac_key=p_input->>'envpac_key' and g.subject_key=p_input->>'owner_subject_key'
      and g.relation_role='owner' and g.standing='active' and g.revoked_at is null
      and (g.expires_at is null or g.expires_at>now())) then
    return jsonb_build_object('standing','HLD','reason','private_environment_owner_current_unresolved');
  end if;
  v_req:=p_input->'request'; v_op:=v_req->>'action';
  if v_op is null or v_op not in ('retain','list','retrieve','organize','remove','surface_intent')
    or exists(select 1 from jsonb_object_keys(v_req) k where k not in
      ('action','asset_key','reference_key','label','folder','tags','target_surface'))
    or (v_op='list' and v_req-'action'<>'{}'::jsonb)
    or (v_op in ('retrieve','remove') and v_req-array['action','reference_key']<>'{}'::jsonb)
    or (v_op='retain' and v_req-array['action','asset_key','label','folder','tags']<>'{}'::jsonb)
    or (v_op='organize' and v_req-array['action','reference_key','label','folder','tags']<>'{}'::jsonb)
    or (v_op='surface_intent' and v_req-array['action','reference_key','target_surface']<>'{}'::jsonb) then
    return jsonb_build_object('standing','HLD','reason','participant_request_boundary');
  end if;
  if exists(select 1 from jsonb_each(v_req) f where f.key in
    ('asset_key','reference_key','label','folder','target_surface') and
    (jsonb_typeof(f.value)<>'string' or length(f.value #>> '{}')>200 or (f.value #>> '{}') ~ '[\r\n]'))
    or (v_req ? 'tags' and (jsonb_typeof(v_req->'tags') is distinct from 'array')) then
    return jsonb_build_object('standing','HLD','reason','participant_request_shape');
  end if;
  if v_req ? 'tags' then
    v_tags:=v_req->'tags';
    if jsonb_array_length(v_tags)>10 or exists(select 1 from jsonb_array_elements(v_tags) t
      where jsonb_typeof(t)<>'string' or length(t #>> '{}') not between 1 and 80) then
      return jsonb_build_object('standing','HLD','reason','participant_tags_shape');
    end if;
  end if;
  with latest as (
    select distinct on (metadata->'my_stash_event'->>'reference_key') metadata->'my_stash_event' as event
    from public.c3_current_evidence_ref where current_state_key=p_input->>'current_state_key'
      and evidence_class='nug_occurrence' and metadata->>'native_process_key'='c3ops_nug_my_stash_v1'
      and metadata->>'envpac_key'=p_input->>'envpac_key'
      and metadata->>'owner_subject_key'=p_input->>'owner_subject_key'
      and metadata->'my_stash_event'->>'contract'='my_stash_private_reference_v1'
    order by metadata->'my_stash_event'->>'reference_key',
      (metadata->'my_stash_event'->>'sequence')::bigint desc)
  select coalesce(jsonb_agg(event->'item' order by event->'item'->>'folder',event->'item'->>'label'),
    '[]'::jsonb) into v_items from latest where event->>'action'<>'remove';
  if jsonb_array_length(v_items)>200 then
    return jsonb_build_object('standing','HLD','reason','stash_bounded_capacity');
  end if;
  select coalesce(max((metadata->'my_stash_event'->>'sequence')::bigint),0)+1 into v_seq
    from public.c3_current_evidence_ref where current_state_key=p_input->>'current_state_key'
      and metadata->>'native_process_key'='c3ops_nug_my_stash_v1'
      and metadata->>'envpac_key'=p_input->>'envpac_key'
      and metadata->>'owner_subject_key'=p_input->>'owner_subject_key'
      and metadata->'my_stash_event'->>'contract'='my_stash_private_reference_v1';
  if v_op='retain' then
    v_key:=nullif(btrim(v_req->>'asset_key'),'');
    select * into v_asset from public.c3ops_asset_record where asset_key=v_key;
    if not found or v_asset.hash_algorithm is distinct from 'sha256'
      or coalesce(v_asset.content_hash,'') !~ '^[0-9a-f]{64}$' or coalesce(v_asset.byte_size,0)<=0
      or nullif(btrim(v_asset.authoritative_custody_type),'') is null
      or nullif(btrim(v_asset.authoritative_custody_provider),'') is null
      or nullif(btrim(v_asset.authoritative_custody_identifier),'') is null
      or nullif(btrim(v_asset.authoritative_custody_location),'') is null
      or nullif(btrim(v_asset.standing),'') is null then
      return jsonb_build_object('standing','HLD','reason','registered_artifact_custody_integrity_unresolved');
    end if;
    if v_asset.custody_controller is distinct from p_input->>'owner_subject_key'
      and v_asset.rights_holder is distinct from p_input->>'owner_subject_key'
      and v_asset.public_retrieval_standing is distinct from 'public_runtime_derivative' then
      return jsonb_build_object('standing','HLD','reason','artifact_reference_access_unresolved');
    end if;
    select item into v_item from jsonb_array_elements(v_items) item where item->>'reference_key'=v_key;
    if v_item is null then
      if jsonb_array_length(v_items)>=200 then
        return jsonb_build_object('standing','HLD','reason','stash_bounded_capacity');
      end if;
      v_item:=jsonb_build_object('reference_key',v_key,'asset_key',v_key,
        'label',coalesce(v_req->>'label',v_asset.title,v_key),'folder',coalesce(v_req->>'folder',''),
        'tags',coalesce(v_tags,'[]'::jsonb),'visibility','private','artifact_snapshot',to_jsonb(v_asset),
        'custody_transferred',false,'ownership_transferred',false);
      v_event:=jsonb_build_object('contract','my_stash_private_reference_v1','sequence',v_seq,
        'action','retain','reference_key',v_key,'item',v_item);
    end if;
  elsif v_op in ('retrieve','organize','remove','surface_intent') then
    v_key:=nullif(btrim(v_req->>'reference_key'),'');
    select item into v_item from jsonb_array_elements(v_items) item where item->>'reference_key'=v_key;
    if v_item is null then return jsonb_build_object('standing','HLD','reason','private_reference_unavailable'); end if;
    if v_op='organize' then
      if v_req ? 'label' then v_item:=v_item||jsonb_build_object('label',v_req->>'label'); end if;
      if v_req ? 'folder' then v_item:=v_item||jsonb_build_object('folder',v_req->>'folder'); end if;
      if v_req ? 'tags' then v_item:=v_item||jsonb_build_object('tags',v_tags); end if;
    elsif v_op='surface_intent' then
      if nullif(btrim(v_req->>'target_surface'),'') is null then
        return jsonb_build_object('standing','HLD','reason','explicit_target_surface_required');
      end if;
      v_item:=v_item||jsonb_build_object('selective_surface_intent',jsonb_build_object(
        'target_surface',v_req->>'target_surface','standing','awaiting_next_governed_boundary',
        'publication_authorized',false,'pac_created',false));
    end if;
    if v_op<>'retrieve' then v_event:=jsonb_build_object('contract','my_stash_private_reference_v1',
      'sequence',v_seq,'action',v_op,'reference_key',v_key,'item',v_item); end if;
  end if;
  return jsonb_build_object('standing','my_stash_resolved','action',v_op,'item',v_item,
    'items',case when v_op='list' then v_items else null end,'my_stash_event',v_event,
    'idempotent_retention',v_op='retain' and v_event is null,'visibility','private',
    'next_boundary',case when v_op='surface_intent' then 'separate_governed_surface_authority_required' else null end,
    'artifact_custody_changed',false,'ownership_transferred',false,'standing_created',false,
    'publication_created',false,'external_effects',0);
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_c3ops_nug_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_b public.c3ops_nug_binding%rowtype; v_field text;
begin
  if jsonb_typeof(p_request) is distinct from 'object' then
    return jsonb_build_object('standing','HLD','missing_predicates',jsonb_build_array('request_shape')); end if;
  select * into v_b from public.c3ops_nug_binding where nug_key=p_request->>'nug_key';
  if not found or v_b.standing<>'active' then
    return jsonb_build_object('standing','HLD','missing_predicates',jsonb_build_array('service_binding'),
      'candidate_missing_predicates',coalesce(v_b.missing_predicates,'[]'::jsonb)); end if;
  foreach v_field in array array['origin_env_key','env_key','envpac_key','current_state_key',
    'executor_ref','execution_instance','capability_ref','authority_oar_key','context_binding_key'] loop
    if nullif(p_request->>v_field,'') is null or p_request->>v_field is distinct from v_b.spec->>v_field then
      return jsonb_build_object('standing','HLD','missing_predicates',jsonb_build_array(v_field)); end if;
  end loop;
  return public.preflight_c3ops_nug_spec_v1(v_b.nug_key,v_b.spec);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_profile_pac_personalization_internal(p_envpac_key text, p_subject_type text, p_subject_key text, p_fields jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_envpac public.c3_envpac%rowtype;
  v_truth jsonb;
  v_pac_key text;
  v_display text;
  v_visibility text;
  v_about text;
  v_interests text;
  v_location text;
  v_open_to jsonb;
  v_item text;
  v_allowed text[]:=array['connect','collaborate','contribute','create','support','learn'];
begin
  if p_envpac_key is null or p_subject_type is null or p_subject_key is null or p_fields is null or jsonb_typeof(p_fields)<>'object' then
    raise exception 'profile_personalization_input_required';
  end if;

  select * into v_envpac from public.c3_envpac
  where envpac_key=p_envpac_key and is_effective=true;
  if not found then raise exception 'envpac_not_effective'; end if;
  if v_envpac.owner_subject_type<>p_subject_type or v_envpac.owner_subject_key<>p_subject_key then
    raise exception 'profile_subject_not_envpac_owner';
  end if;

  v_truth:=public.resolve_profile_pac_v1_internal(p_envpac_key,p_subject_type,p_subject_key);
  if coalesce(v_truth->>'standing','')='profile_not_formed' then raise exception 'profile_not_formed'; end if;
  v_pac_key:=v_truth->>'pac_key';

  v_display:=btrim(coalesce(p_fields->>'display_label',''));
  v_visibility:=coalesce(p_fields->>'visibility_scope','private');
  v_about:=nullif(btrim(coalesce(p_fields->>'about','')),'');
  v_interests:=nullif(btrim(coalesce(p_fields->>'interests','')),'');
  v_location:=nullif(btrim(coalesce(p_fields->>'location_region','')),'');
  v_open_to:=coalesce(p_fields->'open_to','[]'::jsonb);

  if length(v_display)<1 or length(v_display)>160 then raise exception 'display_label_invalid'; end if;
  if v_visibility not in ('private','environment','relational','public') then raise exception 'visibility_scope_invalid'; end if;
  if v_about is not null and length(v_about)>600 then raise exception 'profile_about_invalid'; end if;
  if v_interests is not null and length(v_interests)>400 then raise exception 'profile_interests_invalid'; end if;
  if v_location is not null and length(v_location)>120 then raise exception 'profile_location_invalid'; end if;
  if jsonb_typeof(v_open_to)<>'array' then raise exception 'profile_open_to_invalid'; end if;

  for v_item in select jsonb_array_elements_text(v_open_to)
  loop
    if not (v_item=any(v_allowed)) then raise exception 'profile_open_to_invalid'; end if;
  end loop;

  update public.c3_profile_pac
  set display_label=v_display,
      visibility_scope=v_visibility,
      metadata=coalesce(metadata,'{}'::jsonb)
        || jsonb_build_object(
          'personalization',jsonb_build_object(
            'about',v_about,
            'interests',v_interests,
            'open_to',v_open_to,
            'location_region',v_location
          ),
          'last_update_source','my_environment_owner_update',
          'last_update_at',now(),
          'authority_effect','none'
        ),
      updated_at=now()
  where pac_key=v_pac_key and subject_type=p_subject_type and subject_key=p_subject_key;
  if not found then raise exception 'profile_row_missing'; end if;

  update public.c3_pac
  set release_state=v_visibility,
      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(
        'profile_visibility_updated_by_owner',true,
        'profile_personalization_updated_by_owner',true,
        'profile_personalization_updated_at',now(),
        'authority_effect','none'
      ),
      updated_at=now()
  where pac_key=v_pac_key and envpac_key=p_envpac_key and pac_type='ProfilePAC' and is_effective=true;
  if not found then raise exception 'profile_pac_registry_row_missing'; end if;

  return jsonb_build_object('ok',true,'updated',true,'truth',public.c3_profile_pac_truth(v_pac_key));
end;
$function$

CREATE OR REPLACE FUNCTION public.update_profile_pac_v1_internal(p_envpac_key text, p_subject_type text, p_subject_key text, p_display_label text, p_visibility_scope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_envpac public.c3_envpac%rowtype;
  v_truth jsonb;
  v_pac_key text;
  v_eval jsonb;
begin
  if p_envpac_key is null or p_subject_type is null or p_subject_key is null then
    raise exception 'profile_identity_required';
  end if;

  select * into v_envpac
  from public.c3_envpac
  where envpac_key=p_envpac_key and is_effective=true;

  if not found then raise exception 'envpac_not_effective'; end if;
  if v_envpac.owner_subject_type<>p_subject_type or v_envpac.owner_subject_key<>p_subject_key then
    raise exception 'profile_subject_not_envpac_owner';
  end if;

  if p_display_label is null or length(btrim(p_display_label))<1 or length(btrim(p_display_label))>160 then
    raise exception 'display_label_invalid';
  end if;

  if p_visibility_scope not in ('private','environment','relational','public') then
    raise exception 'visibility_scope_invalid';
  end if;

  v_truth:=public.resolve_profile_pac_v1_internal(p_envpac_key,p_subject_type,p_subject_key);
  if coalesce(v_truth->>'standing','')='profile_not_formed' then
    raise exception 'profile_not_formed';
  end if;

  v_pac_key:=v_truth->>'pac_key';
  if v_pac_key is null or v_pac_key='' then
    raise exception 'profile_pac_key_missing';
  end if;

  update public.c3_profile_pac
  set display_label=btrim(p_display_label),
      visibility_scope=p_visibility_scope,
      metadata=metadata||jsonb_build_object(
        'last_update_source','my_environment_owner_update',
        'last_update_at',now()
      ),
      updated_at=now()
  where pac_key=v_pac_key
    and subject_type=p_subject_type
    and subject_key=p_subject_key;

  if not found then
    raise exception 'profile_row_missing';
  end if;

  update public.c3_pac
  set release_state=p_visibility_scope,
      metadata=metadata||jsonb_build_object(
        'profile_visibility_updated_by_owner',true,
        'profile_visibility_updated_at',now()
      ),
      updated_at=now()
  where pac_key=v_pac_key
    and envpac_key=p_envpac_key
    and pac_type='ProfilePAC'
    and is_effective=true;

  if not found then
    raise exception 'profile_pac_registry_row_missing';
  end if;

  v_eval:=public.c3_pac_evaluate(v_pac_key);
  if coalesce(v_eval->>'completeness_state','held')<>'pass' then
    raise exception 'profile_pac_incomplete_after_update';
  end if;

  return jsonb_build_object(
    'ok',true,
    'updated',true,
    'truth',public.c3_profile_pac_truth(v_pac_key)
  );
end;
$function$
